```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' AND span_name IN ('RoutePlanController.getCheapestRoutes','RoutePlanController.getQuickestRoutes') GROUP BY span_name",
          "claim": "Route-plan getCheapestRoutes and getQuickestRoutes self-time rose to about 1.8 s p50, versus about 50 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.span_name pname, c.service_name csvc, c.span_name cname, count(*) n, quantile_cont(c.duration,0.5)/1e6 child_p50_ms, quantile_cont(p.duration,0.5)/1e6 parent_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND p.span_name IN ('RoutePlanController.getCheapestRoutes','RoutePlanController.getQuickestRoutes') GROUP BY ALL",
          "claim": "The slow route-plan methods have only fast client children (about 20 ms), so the delay is inside the method body itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, avg(value) v, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-route-plan%' AND metric IN ('container.cpu.usage','container.memory.working_set','k8s.container.restarts') GROUP BY metric",
          "claim": "Route-plan CPU is about 0.002 cores against a 5-core limit, memory is flat, and there are no restarts, so this is not resource saturation."
        }
      ]
    },
    {
      "service": "ts-travel2-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='Travel2Controller.adminQueryAll' GROUP BY 1,2",
          "claim": "Travel2 adminQueryAll self-time rose to about 447 ms p50, versus about 22 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.span_name pname, c.span_name cname, count(*) n, quantile_cont(c.duration,0.5)/1e6 child_p50_ms, quantile_cont(p.duration,0.5)/1e6 parent_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel2-service' AND p.span_name='Travel2Controller.adminQueryAll' GROUP BY ALL",
          "claim": "Its repository child TripRepository.findAll takes about 1.6 ms while the parent takes about 447 ms, so the time is in the method body.</br>"
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1",
          "claim": "Other travel2 endpoints such as trips/left are unchanged at about 19 ms p50, so the slowdown is specific to the admin_trip path."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name csvc, p.service_name psvc, count(*) n, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms, quantile_cont(p.duration,0.5)/1e6 caller_client_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-plan-service' AND p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "Travel-plan client calls into route-plan now take about 1.8 s, matching the route-plan server spans."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, count(*) n, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms, quantile_cont(p.duration,0.5)/1e6 caller_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "User-facing ui-dashboard requests to travel-plan now take about 1.8 s, matching the travel-plan server spans."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, count(*) n, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms, quantile_cont(p.duration,0.5)/1e6 caller_client_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-admin-travel-service' AND c.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Admin-travel client calls to travel2 admin_trip take about 445 ms, matching travel2's slow server spans."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, count(*) n, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms, quantile_cont(p.duration,0.5)/1e6 caller_p50_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-admin-travel-service' GROUP BY ALL",
          "claim": "User-facing ui-dashboard calls to admin-travel now take about 790 ms, up from about 65 ms in normal.</br>"
        }
      ]
    }
  ]
}
